<include file="Public:header"/><link rel="stylesheet" href="{pigcms{$static_path}css/bootstrap.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/font-awesome.min.css?t=01"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-fonts.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace.min.css" id="main-ace-style"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-skins.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-rtl.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/global.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui-timepicker-addon.css"><link rel="stylesheet" href="{pigcms{$static_public}layui2/css/layui.css" media="all"/><script type="text/javascript" src="{pigcms{$static_path}js/bootstrap.min.js"></script><script src="{pigcms{$static_public}kindeditor/kindeditor.js"></script><script src="{pigcms{$static_public}layui2/layui.all.js" charset="utf-8"></script>	<div class="mainbox" style="background-color: #fff;min-height: 600px;">		<div class="page_tips">商品限时优惠已过期的或者未开始的不展示在前端，前端最多显示符合的30条数据。排序值越大越靠前显示</div>		<form name="myform" id="myform" action="{pigcms{:U('House/shop_goods_seckill_set')}" method="get">            <div>		    <input type="hidden" name="g" value="System"/>            <input type="hidden" name="c" value="House"/>            <input type="hidden" name="a" value="shop_goods_seckill_set"/>            <input type="hidden" name="frame_show" value="true"/>            <input type="hidden" name="frame" value="1"/>             <a style="line-height: 10px;margin-left: 2px; margin-right: 30px;"  class="btn btn-success" href="javascript:;" onclick="shop_goods_seckill_pop();">添加关联商品</a>            商品名称：<input value="{pigcms{$_GET['goods_name']}" class="col-sm-2" name="goods_name" id="goods_name" type="text" style="float: none;height:35px;margin:10px;width: 180px;" placeholder="请输入商品名称" autocomplete="off"  />            商家或店铺名称：<input value="{pigcms{$_GET['key_name']}" class="col-sm-2" name="key_name" id="key_name" type="text" style="float: none;height:35px;margin:10px;width: 180px;" placeholder="请输入商家或店铺名称" autocomplete="off"  />            业务：<select name="shop_goods_type" id="shop_goods_type" class="col-sm-1" style="float: none;height:35px;margin:10px;width: 110px;">                        <option value="" <if condition="$shop_goods_type eq ''">selected="selected"</if>>全部</option>						<option value="shop" <if condition="$shop_goods_type eq 'shop'">selected="selected"</if>>外卖</option>                        <option value="mall" <if condition="$shop_goods_type eq 'mall'">selected="selected"</if>>商城</option>                        <option value="village_group" <if condition="$shop_goods_type eq 'village_group'">selected="selected"</if>>社区团购</option>					</select>            <input style="line-height: 10px;" class="btn btn-success" type="submit" id="find_submit" value=" 搜 索 " />             <a style="line-height: 10px;margin-left: 20px;"  class="btn btn-success" href="javascript:;" onclick="del_shop_goods_seckill(0);">批量删除</a>            <span class="form_tips"></span>         </div>			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>                         <th  style="text-align:center"><input type="checkbox" class="check_all_box" style="wdith:20px; height:20px;"></th>							<th>ID</th>							<th>商品名称</th>							<th>业务</th>                            <th>商家名称</th>                            <th>店铺名称</th>                            <th>原价</th>                            <th>优惠价</th>                            <th>当前库存</th>                            <th>活动开始时间</th>                            <th>活动截止时间</th>                            <th>商品状态</th>                            <th>排序</th>                            <th class="textcenter">操作</th>						</tr>					</thead>					<tbody class="tbody_container">						<if condition="is_array($result['list']) AND !empty($result['list'])">							<volist name="result['list']" id="vo">								<tr>                                  <td  style="text-align:center"><input type="checkbox" name="selectOnebox[]" class="selectOnebox" style="wdith:20px; height:20px;" value="{pigcms{$vo.id}" onclick="return dAllcheckbox($(this));"></td>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.name}</td>									<td>									<if condition="$vo['shop_goods_type'] eq 'shop'">										<font color="green">外卖</font>									<elseif condition="$vo['shop_goods_type'] eq 'mall'"/>										<font color="green">商城</font>                                    <elseif condition="$vo['shop_goods_type'] eq 'village_group'"/>										<font color="green">社区团购</font>									</if></td>                                    <td>{pigcms{$vo.shop_mer_name}</td>                                    <td>{pigcms{$vo.shop_store_name}</td>                                    <td>￥{pigcms{$vo.price}</td>                                    <td>￥{pigcms{$vo.discount_price}</td>                                    <td>{pigcms{$vo.business_num}</td>									 <td>{pigcms{$vo.start_time_str}</td>                                     <td>{pigcms{$vo.end_time_str}</td>                                     <td>                                    <if condition="$vo['status'] eq 0">										<font color="red">已下架</font>									<elseif condition="$vo['status'] eq 1"/>										<font color="green">已上架</font>									</if></td>                                    <td>{pigcms{$vo.sort}<a href="javascript:void(0);"  style="color: #ef4f1d;font-size: 14px;margin-left: 5px;" onclick="edit_shop_goods_seckill_sort('{pigcms{$vo.id}','{pigcms{$vo.goods_id}','{pigcms{$vo.name}','{pigcms{$vo.sort}');" > 修改 </a></td>									<td class="textcenter">                                        <a href="javascript:void(0);"  onclick="del_shop_goods_seckill({pigcms{$vo.id});" > 删 除 </a>                                    </td>								</tr>							</volist>						<else/>							<tr>                                <td class="textcenter red"  <if condition="$assign_type['type_15']"> colspan="14" <else/>colspan="12"</if>>列表为空！</td>                            </tr>						</if>					</tbody>				</table>                {pigcms{$result.pagebar}			</div>		</form>	</div><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }   .mdfy_shop_goods_seckill_sort .divp{    margin: 25px; }</style><script type="text/javascript">   function shop_goods_seckill_pop(){         var url = "{pigcms{:U('House/shop_goods_seckill_pop')}";         var index_m= layer.open({            type: 2,            title:"选择商品",            content: url,            area: ['1000px', '550px'],            offset:['30px','180px'],            btn: ['确定','关闭'],            maxmin: false,            yes: function (index,layero) {                var xbody = layer.getChildFrame('body', index); //得到iframe页的body内容                var goods_type = xbody.find("#goods_type").val()||'';                var selectVboxObj = xbody.find('.tbodyContainer input[type="checkbox"]:checked');                if(selectVboxObj.size()<1){                     layer.alert('请至少选择一个商品', {icon: 2});                     return false;                }                if(!goods_type){                     layer.alert('业务类型错误！', {icon: 2});                     return false;                }                console.log('goods_type',goods_type);                var goods_id_arr=[];                selectVboxObj.each(function(){                    var goods_id=$(this).val()||0;                    var oneData={goods_id:goods_id};                    oneData.a_id=$(this).data('a_id')||0;                    oneData.goods_name=$(this).data('goods_name')||'';                    oneData.store_name=$(this).data('store_name')||'';                    oneData.merchant_name=$(this).data('merchant_name')||'';                    oneData.price=$(this).data('price')||0;                    oneData.discount_price=$(this).data('discount_price')||0;                    oneData.stock_num=$(this).data('stock_num')||0;                    oneData.goods_status=$(this).data('goods_status')||0;   //0下家 1上架                    oneData.active_start_time=$(this).data('active_start_time')||'';                    oneData.active_end_time=$(this).data('active_end_time')||'';                    oneData.url=$(this).data('url')||'';                    oneData.img=$(this).data('image')||'';                    goods_id_arr.push(oneData);                });                var postArr={goods_arr:goods_id_arr,goods_type:goods_type};                $.post("{pigcms{:U('House/shop_goods_seckill_save')}",postArr,function(result){                    if(result.err_code == 1){                        layer.msg('保存失败了 ',{offset:['25%','45%']});                    }else{                        layer.msg('保存成功了',{offset:['25%','45%']});                    }                },'json');                 setTimeout(function(){                    layer.close(index_m);                     window.location.href="{pigcms{:U('House/shop_goods_seckill_set')}&frame_show=true&frame=1";                },2000);            },        });   }    function edit_shop_goods_seckill_sort(idd,goods_id,goods_name,sort){            var xcontent='<div class="mdfy_shop_goods_seckill_sort"><div class="divp" style="color:#147404;">注意：排序值越大越靠前显示</div><div class="divp">现在的排序值是：'+sort+'</div><div class="divp"><span>请输入修改值：<input value="'+sort+'" class="xsort" type="number" style="width: 160px;" placeholder="请输入修改数据"  oninput="this.value = this.value.replace(/[^\\d]/g, \'\');" autocomplete="off" max="99999999" min="0" /><span></div></div>';            var index_n= layer.open({            type: 1,            title:"修改商品【"+goods_name+"】排序值",            content: xcontent,            area: ['450px', '300px'],            offset:['50px','35%'],            btn: ['确定','关闭'],            maxmin: false,            yes: function (index,layero) {                //var xbody = layer.getChildFrame('body', index); //得到iframe页的body内容               xsort= $('.mdfy_shop_goods_seckill_sort .xsort').val()||0;               console.log('xsort',xsort);                var postArr={idd:idd,goods_id:goods_id,xsort:xsort};                $.post("{pigcms{:U('House/edit_shop_goods_seckill')}",postArr,function(result){                    if(result.err_code == 1){                        layer.msg('保存失败了 ',{offset:['25%','45%']});                    }else{                        layer.msg('保存成功了',{offset:['25%','45%']});                        setTimeout(function(){                            layer.close(index_n);                            window.location.href="{pigcms{:U('House/shop_goods_seckill_set')}&frame_show=true&frame=1";                        },2000);                    }                },'json');            },        });   }    function del_shop_goods_seckill(idd){       var iddtmp=idd ? idd*1:0;       var idd_arr=[];       var tips='你确定要删除商品数据吗？';       if(iddtmp>0){            idd_arr.push(iddtmp);       }else{           tips='你确定要删除选中的商品数据吗？'          if( $('.tbody_container input[type="checkbox"]:checked').size() <1){                   layer.alert('请至少选择一个商品', {icon: 2});                   return false;          }          $('.tbody_container input[type="checkbox"]:checked').each(function(){                    var iddd=$(this).val()||0;                   idd_arr.push(iddd);            });       }       layer.confirm(tips,{                icon:3,                btn: ['确定删除', '取消']            },function(index,layero){               var postArr={idd_arr:idd_arr};                $.post("{pigcms{:U('House/del_shop_goods_seckill')}",postArr,function(result){                    if(result.err_cod == 1){                        layer.alert('删除失败了 ',{icon: 2});                    }else{                        layer.alert('删除成功了',{                        });                        layer.close(index);                        window.location.href="{pigcms{:U('House/shop_goods_seckill_set')}&frame_show=true&frame=1";                    }                                    },'json');		}, function(index){                //按钮【按钮二】的回调        });    }    $(".check_all_box").on('click',function(){        if($(this).is(':checked')){            $("input[name='selectOnebox[]']").prop("checked",true);        }else{            $("input[name='selectOnebox[]']").prop("checked",false);        }    });    function dAllcheckbox(e){        var n=0;        var len = $("input[name='selectOnebox[]']").length;        for(var i=0;i<len;i++){            if($("input[name='selectOnebox[]']")[i].checked){ n++; };        }        if(n==len){            $(".check_all_box").prop("checked",true);        }else{            $(".check_all_box").prop("checked",false);        }    }</script><include file="Publics:footer"/>